from build_cards import *
R='亚洲之鹰罗开系列/'
def rc(*args,**kw):return card(*args,series=['亚洲之鹰罗开系列'],**kw)

rc('luokai','罗开',aliases=['亚洲之鹰','鹰'],roles=['主角'],bio='罗开在印藏一带长大，自幼受过控制身体与脑部活动的训练。他喜欢独来独往，也能在城市享乐、雪山静坐和危险探险之间切换。神秘组织以情报给他财富，又以追踪与互相残杀的规则侵犯他的自主；他拒绝按命令杀陌生人，这份愤怒比任何报酬都更能驱动他。对付时间大神时，他凭借被复制思想的联系反向影响假人，却也会被关于天使的幻象诱惑，最终靠她牺牲才活下来。此后的罗开既见识了外星力量，也留下了失去爱人的创伤。他帮助卡娅、燕艳、水荭等人，并不总能正确理解她们的心愿；他向往自由，仍会不自觉地替女性解释选择。在《异人》中，他坚持三晶星机械人与天敌可以不互相毁灭，在《飞焰》中又阻止求生的外星灵魂用揭穿秘密威胁卡娅。综合终局，他的真正强项是把疑团化为可行动的问题、在绝境中抓住有限条件，以及不肯让关系沦为主从。他可以犯傲慢、情欲和保护过度的错误，随后必须面对别人的回答，而不是成为每次都洞见一切的旁白。',appearance='身形魁伟、体格强健；常被称为鹰，能以细微化妆改变外貌。',endpoint='《飞焰》结尾仍在帮助受困的八角星灵魂并替水荭寻找可核实的情报；没有得到外星人的全部科技。',ability=[A('冒险技艺','熟悉格斗、化装、潜行、驾驶和多地生活方式，现场寻找可用路径。',['近战摔投、解缚','驾驶和潜水脱险','跨文化调查'],'仍是血肉人，药物和信息缺失会使他失手。'),A('催眠与脑活动控制','童年训练使他能集中意志、自我控制，并曾借敌方建立的思想复制通道反向影响假人。',['催眠询问信息','在麻醉前采取准备','利用既有脑讯号连接反制'],'不是任意控心；反向操纵依赖敌人先连接思想，仍会受幻象和欲望影响。',kind='精神训练')],evidence=[E(R+'01鬼钟.txt',222,227,'拒绝杀戮指示'),E(R+'01鬼钟.txt',746,766,'麻醉弱点与脑训练'),E(R+'02妖偶.txt',1300,1315,'有条件反制复制人'),E(R+'03魔像.txt',1252,1268,'天使牺牲'),E(R+'10异人.txt',1385,1394,'主张和平共处'),E(R+'15飞焰.txt',1189,1227,'保全卡娅和水荭')],motivation='保持独立，保护具体的人，追索异常而不接受任何力量的奴役。',triggers=[T('有利交易要求杀无关者','对方把服从当资格','拒绝并寻找幕后控制手段，宁愿失去利益。'),T('强者认为敌类必须消灭','双方仍有对话空间','要求具体说明伤害，再设计互不侵犯的条件。'),T('朋友的秘密可换救援','公开会被用作胁迫','制止拿秘密勒索，另找能落实的营救路径。')],scores=(4,1,1,4,3,6),limits=(2,1,1),reasoning='自由不只是自己的，也包括别人不按他的设想生活的权利。',ordinary='自信、好奇，时有嘲讽；对亲近的人会显出保护欲与笨拙。',mind='受过高阶催眠与集中训练，但《魔像》证明仍可被逼真欲望幻象控制。',destruction='熟练格斗能伤成人、把轻质机械人摔撞石台；不具大范围能量破坏。',speed='近身反应、攀爬和运动优于常人，无证据达到枪弹速度。',theoretical='凶')

rc('baoe','宝娥',roles=['反派'],bio='宝娥用令人着迷的外貌、秘密情报和精细技术把冒险者纳入自己的网络。罗开一度只能感觉到组织知道他的每一步，却不知道眼前的女人就是控制者；一次看似普通的牙齿清洗，已足以在他不察觉时留下追踪手段。她安排成员以死亡筛选，利用活机械人的研究把人变为接收外部指令的工具，也会因嫉妒杀害花灵。她并非只会撒娇的接头人，能观察对方细微反应，在情绪突变后迅速恢复镇定，指尖藏针又让近身接触随时变成麻醉。可是她也会解释太多，希望听见自己魅力得到承认，在提醒对手将被麻醉时留下准备空隙。她受时间大神控制的体系最终在计算机室爆炸中崩溃，死亡信息经设备传到高达，继续引出后来的调查。终局参战应恢复她生前最后可行动形态，不能把死亡后的记录当作无限复活。她最危险的地方是把愉快的接触、真实的利益与逐渐增加的服从要求接在一起；一旦被揭穿，才露出她希望把人的意志一并占有的底色。',appearance='极美的成年女性，手指修长，能精细化装；声音甜柔而可迅速转冷。',endpoint='计算机室爆炸死亡，《妖偶》确认；组织与时间大神联系被揭露。',deploy='演绎改编：恢复最后可行动身体及指尖装置，不恢复整个已毁组织。',adapt=[{'change':'恢复死亡前可行动形态，保留组织覆灭记忆。','reason':'使反派能在新局面改变手段，而不是重复既定陷阱。','power_impact':'无新增权限；组织设备须重获。'}],ability=[A('隐蔽控制与接触麻醉','以伪装、微型追踪和指尖针装置削弱目标，再交由设备控制。',['隐蔽接近','药针制伏','以情报和欲望招揽'],'需近身和药物；不能隔空夺取任意人意志，活机械人需手术设备。')],evidence=[E(R+'01鬼钟.txt',716,748,'身份、追踪与药针'),E(R+'01鬼钟.txt',754,766,'嫉妒、麻醉与漏洞'),E(R+'02妖偶.txt',429,551,'死亡信号及上位控制者')],motivation='把有价值的冒险者纳入可操纵的秩序，并维护自己对他们的支配。',triggers=[T('目标被利益吸引','尚不知道组织规则','先提供确有价值的情报，再递进提出义务。'),T('对方识破身份','仍在可接触距离','保持亲近表象，利用药针夺回局面。'),T('魅力被拿来比较','触及自尊和嫉妒','短暂失态后迅速收束，可能把惩罚变成控制。')],scores=(2,0,1,2,1,4),limits=(1,2,1),reasoning='她以为控制比互信可靠，因而把人降为功能。',ordinary='甜柔、善变，观察极细；不把所有女性共同写成嫉妒本能。',theoretical='并')

rc('sulatuolie','素拉脱烈',aliases=['紫色蜥蜴'],roles=['反派'],bio='素拉脱烈的名字既来自剧毒蜥蜴，也成为一位顶尖杀手的代号。她以精妙的全身化妆接近罗开，使自己看起来像当地女郎，真正的身份在攻击发生前几乎无人知晓。她惯于把带毒器物藏进亲密接触之中，让微小伤口成为致死入口，并把不引起恐惧的死亡当成技术完成度的一部分。神秘组织却没有把她当不可替代的人，而把她与罗开放进一场双方信息并不相等的生死筛选。毒最终落到她自己身上，她才追问这是否公平，并理解组织要的只是留下胜者。临死前她重新评价自己的手艺：复杂而自以为完美的做法反而给了对方发现的机会，最直接的普通攻击可能更有效。她没有时间实行这个认识，死亡很快使身体僵硬。作为终局参战的明确恢复版本，她可以带着这个失败记忆，在炫示技巧与直接执行之间发生新的选择；但不能凭代号增加蜥蜴生理、免疫自身毒素或无条件一击必杀。',appearance='实际肤色不明，能伪装成当地女郎；身份主要由毒杀手法识别。',endpoint='《鬼钟》中反受自身剧毒而死亡。',deploy='演绎改编：恢复最后可行动的杀手身体并保留失败认知；毒具数量有限。',adapt=[{'change':'恢复最后行动形态，保留临死对手法的反省。','reason':'让她调整选择而非照搬同一刺杀。','power_impact':'不增加抗毒、毒源或杀伤范围。'}],ability=[A('伪装与隐蔽施毒','以化装和接近掩护带毒器物，靠伤口致毒。',['秘密刺杀','伪装渗透','威慑近身者'],'毒必须真实接触伤口；自身同样受毒，目标识破可反制。')],evidence=[E(R+'01鬼钟.txt',260,265,'身份与毒杀方式'),E(R+'01鬼钟.txt',269,279,'筛选、反省和死亡')],motivation='完成任务并证明专业价值，终局记忆使她会怀疑把自己当消耗品的雇主。',triggers=[T('雇主信息不对等','隐瞒目标与风险','要求补足情报，辨别是否只是筛选牺牲品。'),T('能不显眼接近目标','伪装仍未暴露','选择最少动作的机会，不必表演复杂仪式。'),T('毒具脱离控制','可能反伤自身','立刻撤离或弃具，不宣称免疫。')],scores=(2,1,0,1,1,4),limits=(1,1,1),reasoning='把人当筛选工具的组织并不尊重专业；技巧须服务真实效果。',theoretical='并')

rc('time_god','时间大神',roles=['反派'],bio='时间大神以钟面和神秘信号建立自己的威慑，让地球人很容易把难解的技术误作无所不能的神力。它通过宝娥、活机械人和复制玩偶影响现实，而不是始终能够亲自到任何地方完成事情。为了让假人更像罗开，它读取和转移思想，也因此给罗开留下反向干预的通道。进入它所在空间后，罗开又发现意志并非稳固护盾，逼真的天使幻象足以使他明知危险仍想靠近；这种操纵会利用对象自己最难舍弃的欲望。天使以牺牲攻击它、毁掉它握有的东西，斯波达星人又继续追捕，它却没有因此被确认彻底消灭。《怪头》末尾，它与罗开、卡娅一同被封在山腹，衰弱得只剩暗蓝光团，不得不用手语请求合作。依靠遗留仪器与脑能力，双方共同脱困，它恢复明亮后离去并许诺。终局不能把先前的狂言当绝对时间统治，也不能把受创抹去；它适合成为擅长代理控制、交换和欲望陷阱的危险存在，必要时会求助敌人，承诺是否可靠仍是下一次互动的张力。',appearance='可呈强光或暗蓝光团，也能变成手的轮廓表达手语；钟面意象是显现方式。',endpoint='《怪头》受创后借仪器与罗开合作脱困，光团飞走，未确认死亡。',ability=[A('思想信号、幻象与代理控制','借设备或连接读取思想、影响感官，并使用受控代理和复制人。',['制造逼真诱惑','控制已有连接的代理','通过变化的光形交流'],'并非随时全知；连接可成为反向通道，设备与能量受创会削弱行动。',kind='外星精神与技术'),A('异空间活动','在其可接触的空间中活动并影响进入者。',['藏匿和设局','利用空间入口'],'不是可自由改写历史；被封山腹时仍需外援与仪器脱困。',kind='空间相关能力')],evidence=[E(R+'02妖偶.txt',1143,1183,'思想复制的条件'),E(R+'03魔像.txt',1140,1178,'感官陷阱'),E(R+'03魔像.txt',1252,1261,'受创'),E(R+'04怪头.txt',1287,1346,'虚弱与合作脱困')],motivation='保全存在并恢复影响力，把他人的欲望变成可利用的依附。',triggers=[T('强敌正面压制','力量或设备不足','退入可保全的空间，转用代理或谈判。'),T('对象有无法舍弃的愿望','能建立感官或思想接触','提供几乎真实的满足，诱导主动放下戒心。'),T('与敌人共同被困','只有合作能离开','提供关键知识换行动，承诺需在后续验证。')],scores=(3,6,4,4,5,6),limits=(1,4,2),reasoning='支配欲强但会为生存妥协；自称神不等于不受条件限制。',mind='可影响感官和思想，但罗开利用复制连接反制成功；受创后能力明显下降。',energy='强光显现与设备相关能量，具体上限未量化。',durability='可在多次攻击后残存光团；仍会受创、受困，不是不死无敌。',speed='光团可以高速离去，未给可换算极限；不能把光芒外观直接换成光速。',theoretical='狂')

rc('tianshi','天使',roles=['主角'],bio='天使以地球美女的形象来到罗开身边，使他接触到油画背后的另一空间和时间大神的秘密。她来自八等旋转星，借用地球人能接受的外形并不等于她的原生身体也符合人类审美；这一差别后来被敌人用来羞辱和诱惑罗开。她与族人原有明确任务，要夺回或毁去落在时间大神手中的重要之物，罗开的进入也是计划的一部分。可是当罗开被幻象引得放弃抵抗，按原计划等待已不能救他，天使擅自启动最强的能量环节，冒着代价突破空间限制，以真实形态冲向敌人，并提示罗开怎样使用通讯仪协同。重要之物被毁，时间大神受伤，她自身生命也消失。族人把经过告诉罗开，并把古堡转到他名下，无法填补的失去仍留在那幅画前。恢复参战时，天使保留的是有任务、有感情且会越过纪律救人的人格；不能把全族最强装置永久装进她身体，也不能说牺牲已经让她获得无限复生。',appearance='可用美丽地球女性形象出现；原生形体与人类显著不同，不能只用“怪物”概括其人格。',endpoint='救罗开进入异空间攻击时间大神后生命消失。',deploy='演绎改编：恢复最后可行动形态与终局记忆；跨空间强行救援仍需族人装置和高能量。',adapt=[{'change':'恢复牺牲前行动资格，保留越权救人的选择记忆。','reason':'提供任务与感情的新冲突，不重复命定牺牲。','power_impact':'不新增复活次数，不自动拥有全族装置。'}],ability=[A('外星形态与技术接口','以地球人形象交往，使用族人通讯、能量与空间相关装置。',['跨文化接近','信息警告','有设备条件的空间救援'],'最强突破耗尽条件且造成死亡；设备权限与供应需明确。',kind='外星技术')],evidence=[E(R+'03魔像.txt',1132,1151,'族属、伪装与敌方利用'),E(R+'03魔像.txt',1178,1191,'协同攻击'),E(R+'03魔像.txt',1239,1268,'牺牲原因与结局')],motivation='完成族人任务，同时不愿放弃已陷入绝境的爱人。',triggers=[T('任务与营救发生冲突','等待将使同伴失去自主','评估设备代价后选择介入，明确承担越权。'),T('外形被用来羞辱','对方以人类审美否定关系','把选择与行动摆在前面，不以变美交换人格尊重。'),T('伙伴遭感官诱惑','仍有一次通讯机会','传递最关键的识别和动作提示，避免长篇解释延误。')],scores=(2,4,2,2,3,4),limits=(1,4,2),reasoning='真实关系不能只依赖借来的外貌；救人必须承担实际能量代价。',ordinary='亲近而有目的；危急时会不顾既定安排行动。',theoretical='凶')

rc('daina','黛娜',roles=['重要配角','阶段性对立者'],bio='黛娜是受严格组织训练的情报人员，也是罗开在时间大神事件后保持密切关系的人。初见时武器和误会使两人并非天然盟友，此后她的工作身份仍不断介入私人生活：水银将军通过她寻找罗开，机密任务又要求她保留不能全说的部分。她被拍下向时间大神膜拜的影像，高达据此怀疑她已受控制，真正的原因却是她试图用这一动作引出对方。与此同时，能够长大成为她的玩偶确实制造了另一个危险版本，使本人行为、别人观察和假人行动互相纠缠。罗开与她被困时，她愿意听懂推理，配合判断，而在返回办公室看到那个缩回的复制玩偶后，她强烈要求彻底毁掉它。这个反应表现的不是怕所有奇异事物，而是对自己被替代、被他人拿去行动的真实恐惧。后来她又与卡娅、水荭一起接触外星装置和曲如眉的故事。综合终局，她有情报能力和爱人的柔情，也有机构纪律；她不会因为亲密便自动交出所有秘密，更不会把复制人的行为当成本人的意愿。',appearance='高大健硕而美丽的女性，与娇小的卡娅形成明显体型对照。',endpoint='后期仍为组织工作的特工；复制玩偶已毁，外星设备是共同保管资源。',ability=[A('特工行动与组织协调','受专业训练，可执行武装任务、调查和情报联络。',['枪械威慑','隐蔽接触','协调组织资源'],'机构资源有任务与权限约束；不是自动拥有外星科技。')],evidence=[E(R+'01鬼钟.txt',708,708,'持来福枪对峙回忆'),E(R+'02妖偶.txt',1262,1319,'假象、真伪与毁偶'),E(R+'04怪头.txt',328,571,'水银将军与工作'),E(R+'15飞焰.txt',978,978,'共同保管装置条件')],motivation='在职责、感情与个人自主之间保留真实选择，拒绝被复制替代。',triggers=[T('证据显示自己做了怪事','影像与自身记忆冲突','先核对替身和任务背景，不把影像等同意愿。'),T('上司要求借私人关系办事','对象明确不愿受组织支配','说明任务而承受拒绝，不把亲密当命令权。'),T('可复制自己的装置仍存在','没有可靠控制和隔离','主张销毁或严格封存，避免再被利用。')],scores=(3,0,1,3,3,5),limits=(2,1,1),reasoning='任务需要保密，感情不应成为剥夺自主的工具。',ordinary='能干直接，情感强烈，遇到自己的替身会警惕。',theoretical='强')

rc('kaya','卡娅',roles=['重要配角','阶段性对立者'],bio='卡娅曾是苏联情报体系里的上校，娇小外形并不妨碍她执行机密任务。她与罗开一同卷入怪头和时间大神的冲突，被封在山腹时，强大的外星阵营也没有把两个地球人的生命放在优先位置。她急于求生，提出向同样被困的敌人求助，这一务实念头推动了最后的合作。她一度以把自己献给罗开的极端许愿表达获救后的感情，但后来的生活并没有固定为谁的附属。遇到哈德后，她认为找到了理想伴侣，离开权位与组织的轨道，与他共同生活；她不知道哈德是三晶星机械人，因此这一段关系同时承载着真切幸福与被隐瞒的事实。《飞焰》中外星灵魂需要哈德援助，罗开明确反对用揭穿身份威胁她，可见她不是随时可调用的通行证。终局参战的卡娅应保留专业能力、求生时的机变和主动投向爱情的决心，也保留对伴侣身份尚未获知的边界。她可以选择帮助旧友，但选择应由请求和信任促成，不能由他人替她规定。',appearance='身形娇小，双眼清澈；原为上校，行动训练与柔和外观并存。',endpoint='与哈德离开观察地带在地球隐居，组织未找到她；尚不知道伴侣为机械人。',ability=[A('特工技能与危机谈判','以训练处理危险环境和机密任务，绝境中愿尝试敌我交换。',['侦察与自保','寻找合作脱困条件','与旧友联络'],'退出机构后不能默认调用原组织；哈德能力不属于她。')],evidence=[E(R+'04怪头.txt',1260,1349,'绝境合作与脱困'),E(R+'10异人.txt',1275,1281,'与哈德的关系'),E(R+'15飞焰.txt',1137,1139,'离开组织与隐居'),E(R+'15飞焰.txt',1177,1204,'未知身份与援助')],motivation='把自己的人生从命令中取回，保护所相信的亲密关系。',triggers=[T('共同被困','敌人也需要离开','提出有限合作并追问各方实际条件。'),T('旧友求援','消息可确认并说明风险','愿带着伴侣协助，仍保留自己的决定。'),T('有人以秘密胁迫','要求牺牲关系换利益','先核实消息来源，拒绝把恐惧直接变成服从。')],scores=(3,0,1,3,2,4),limits=(1,2,1),reasoning='求生与感情都可以成为自主选择，不该被机构和朋友代替。',ordinary='娇小而果断，亲密时热切；对不熟悉的外星事实仍可能误判。',theoretical='并')

rc('yanyan','燕艳',roles=['主角','重要配角'],bio='燕艳最初以美丽而主动的女性接近罗开，但她追索的并不是普通古物。她来自另一个星球，与四千年前的地球经历相连，在现代生活十年之后仍想弄清同伴和回乡的可能。罗开给她取了中文名字，她则用古老语言和对本星生命的敏锐感觉，帮助找到迷宫中的隐秘石室。她原来所属的秩序把美丽女性当作牺牲物，这段经历使柔顺和恐惧成为她的表面样貌，却不意味着她没有自己的愿望。巨龙内部的真相揭开后，控制者原来是依赖光源的机械人，回乡道路未能实现；她注意到强光可能让它们恢复，但罗开不愿冒使危险武器重启的风险。她留在克里特岛与罗开相处，知道他终究不能一直停留。后期罗开仍回来见她，也向她谈别人的爱情难题。综合终局，她是被迫适应新世界的异乡人，既能享受安稳，也会记得没有被满足的回归愿望；演绎不能把她写成永远只会顺从的奖励人物，更不能把巨龙算作她随身拥有的武器。',appearance='金色长发，美丽的女性外形；现代化装和饰物可显得主动明艳。',endpoint='留在克里特岛生活，与罗开保持关系；未获回乡和启动巨龙的能力。',ability=[A('同星生命感应与古语','对自身星球生命具有实在的第六感，能理解四千年前相关语言。',['寻找同类遗迹','翻译古老指令','辨认异常联系'],'不是感知所有生命或预知未来；不能凭感应操纵巨龙。',kind='异质感官')],evidence=[E(R+'05巨龙.txt',90,142,'名字、现代身份与目标'),E(R+'05巨龙.txt',927,956,'感应与发现'),E(R+'05巨龙.txt',1221,1277,'古语、光源与回乡受阻'),E(R+'10异人.txt',1396,1397,'持续关系')],motivation='在异乡得到自主生活与真实关系，并保留寻找故乡的愿望。',triggers=[T('出现与故乡有关的迹象','自身感应与环境相合','主动指出方向并解释感受，要求亲历核对。'),T('保护者替她决定未来','以柔弱为理由省略询问','清楚说出自己的愿望，即使暂时接受现实。'),T('危险设备可能通向故乡','代价牵涉别人','要求一起查明安全条件，不把渴望当作全权许可。')],scores=(1,1,1,2,1,1),limits=(1,3,1),reasoning='安稳不能消除归属问题，柔顺也不是没有意志。',ordinary='情感细腻，熟悉问题会主动发问；避免把她缩成单一依恋姿态。',theoretical='纸')

rc('fenghou','蜂后',aliases=['蜂后王国女皇'],roles=['反派','重要配角'],bio='蜂后创立了由美女组成的隐秘王国，把亲密关系当成渗透政治与权力的工具。成员带着各自野心前来，她则用教母、女皇和组织中心的身份使这些分散的欲求成为行动。她希望拥有神庙作为王国象征，派水晶妙人儿请求罗开代为购买，随后又在蛇神庙探险中试图控制局面。得知所谓宝石会恢复为普通石头，她的财富计划落空；更大的困境在于王国已经威胁到各国权贵，使非常物品交易会背后的势力决定介入。蜂后自信可以征服男人，却不能强迫浪子高达长久表白。后来出现在她面前的高达显得全心投入，她认定这才是真正爱她的人；事实是勒曼医院复制了高达，并移植了他对她的爱情记忆。复制人的感情并非演戏，他还发展出抵抗外加命令的意志。蜂后最终与这个独立的人离开，摆脱跟踪，隐居地点不明。综合终局不把她继续扩张全球王国写成必然使命：她已经得到自己真正看重的关系，但仍保有组织者的判断、占有欲及对背叛的敏感。',appearance='极有魅力的成年女性，习惯处于精心布置的权力空间；镜面环绕给她安全感。',endpoint='与高达复制体经哥本哈根、马达加斯加后失去踪迹，罗开判断她不再以扩张威胁他人。',ability=[A('关系组织与隐秘渗透','招揽成员、利用人情与欲望影响有权者，安排代理行动。',['情报获取','组织交涉','筹集行动资源'],'影响必须通过具体关系落实；不能直接精神控制，隐居后组织随调权限不确定。')],evidence=[E(R+'06蛇神.txt',145,205,'组织信条、委托与保密'),E(R+'06蛇神.txt',1444,1452,'计划失败'),E(R+'07蜂后.txt',12,18,'组织结构与安全感'),E(R+'07蜂后.txt',1122,1162,'复制人的爱情与离去')],motivation='维护自身选择与爱人的真诚，终局更愿守住二人生活而非继续征服。',triggers=[T('关系被当作买卖','第三方声称拥有她或爱人','先核实控制渠道，再切断交易的筹码。'),T('组织利益与私人幸福冲突','幸福已可真实维持','允许退出扩张，不为女皇名号牺牲关系。'),T('有人以感情掩饰命令','爱人的行动与本意矛盾','追查外部操纵，不把一次异常立即判作背叛。')],scores=(1,0,1,2,1,3),limits=(2,2,1),reasoning='征服者也会希望被真心选择；爱情不是组织可以配发的奖赏。',ordinary='从容、善于衡量他人的欲望；关系受威胁时强烈而直接。',theoretical='并')

rc('shuijing','水晶妙人儿',roles=['重要配角','阶段性对立者'],bio='水晶妙人儿是两个外貌相同、共用这一称呼的成年女子，文本没有给她们可稳定区分的个人姓名。她们不是一个人的任意分身，而是作为一对行动、共享强烈感受的搭档，与蜂后有教母关系，属于王国核心。高达介绍她们时，连自己也会因与蜂后的牵连而窘迫；她们则善于利用这种气氛，把真正的委托藏在轻松亲昵的交往之后。为取得蛇神庙，她们熟记交易会说明，逐步解释价格、地点和无法亲赴的理由，并要求罗开在事情未成前不要公开与王国的联系。她们知道美貌和配合会影响对方，却并不只是被递送的礼物：她们会指出罗开过早作出的判断，控制谈话顺序，主动提出组织的保密条件。后来的王国危机表明，这种人际手段不能抵抗更强的外部操控。综合演绎把她们作为双人条目，是为了忠实保留原文不可区分的身份结构；每次行动仍只有两具身体，两人的感受联动也不能扩张成读取所有人的思想。',appearance='相貌相同的两名成年女性，浅蓝眼睛，动作与神态常保持同步。',endpoint='《蛇神》《蜂后》王国事件中的双人核心成员；蜂后离去后去向未有明确交代。',ability=[A('双人同步与社交游说','熟练配合行动，原文显示两人感受有异常同步，借此形成联合交涉。',['双人接近','信息说明和保密联络','互相补足现场观察'],'仅限这两位既定人物；没有任意分身、异地全知或强制控心证据。')],evidence=[E(R+'06蛇神.txt',65,91,'同名双人及组织身份'),E(R+'06蛇神.txt',128,146,'同步感受'),E(R+'06蛇神.txt',159,208,'委托、反驳与保密')],motivation='在彼此配合中维持自主和亲近关系，完成确已接受的组织任务。',triggers=[T('被当作没有意见的礼物','对方省略询问','一起纠正交易前提，再说明愿意做什么。'),T('任务需要保密','身份公开会破坏条件','约定接触方式而暂时退开。'),T('外人试图分化她们','提供互相矛盾的信息','交换观察后共同决定，不凭外人标签争胜。')],scores=(2,0,1,2,1,3),limits=(1,2,1),reasoning='配合是既有关系与异常感受的结果，不能被随意拆成可替换工具。',uncertainties=['两人没有分别命名，不能捏造个人生平；同步机制没有科学说明。'],theoretical='并')

rc('angeren','安歌人',roles=['主角','重要配角','阶段性对立者'],bio='安歌人懂得购买稀罕情报，也懂得把风险与诱惑一起带到冒险者面前。蛇神庙事件中，她花钱获得资料，与罗开共同进入水下遗迹，期待无数宝石，最后只找到外星来客留下的说明。宝石期限已经过去，蜂后的计划也因此失去依据，她却认为与罗开共同经历的时间仍值得代价。到了天神之盒的故事，她的愿望更清楚：希望借许诺得到所爱的人。罗开在月球看到许多求解者的干尸而愤怒，她仍坚持问题出在解法，不肯因为别人的失败放弃那一只盒子。两人因而发生真正分歧，亲密不能消除她的执着。雷雪终于传达盒上的讯息，许诺必须以舍弃肉体生命为条件，安歌人感到惊惧与失望，踏扁盒子，却没有选择死亡。终局的她仍是有行动力、善于谈判的人，也已经知道愿望不能只凭一件神物兑现。她会为所爱付出，但不应被写成必然自毁的执念机器；那次拒绝本身就是她保留生活的选择。',appearance='美丽的成年女性，谈话时可柔和亲近，面对所求之物会露出明显执着。',endpoint='《解开死结》知晓许诺代价后拒绝以死亡求偿，毁掉一只天神之盒。',ability=[A('情报购买与探险执行','用资金取得线索，能配合潜水、外星交通设备和危险环境调查。',['寻找隐秘资料','共同潜水脱困','谈判交换'],'设备靠获得与学习，不能因上过月球就拥有星际航行能力。')],evidence=[E(R+'06蛇神.txt',1417,1450,'水下行动与情报代价'),E(R+'11死结.txt',1307,1329,'坚持盒子与关系冲突'),E(R+'12解开死结.txt',1230,1278,'死亡讯息、拒绝与毁盒')],motivation='争取自己想要的感情与经历，同时保留继续生活的资格。',triggers=[T('珍稀线索可购买','来源有可核实内容','衡量价格与风险，争取亲自参与。'),T('伙伴因失败要求放弃','规则仍有未验证部分','提出具体再试条件，不仅以感情相逼。'),T('愿望要求失去生命或意志','代价已被证明','允许愤怒与失望，选择拒绝而重新安排生活。')],scores=(2,0,1,2,1,3),limits=(2,2,1),reasoning='愿望很强烈，但终局证明她并不愿以失去自身换来空洞满足。',theoretical='并')

rc('qu_rumei','曲如眉',roles=['主角','重要配角'],bio='曲如眉看似古典侠女，懂中国武术，也有超出普通人寿命的经历。她和八角星人的相爱不是一次新奇邂逅：对方以灵魂形态来到地球，改变了她细胞的基本组织，使她必须每隔五百年经历一次重生。她称自己如经火再生的凤凰，这句话后来才得到具体解释，并非可以随时焚烧复活的战技。为了帮助被困的爱人，她寻找传送设备，与高达、罗开既合作又隐瞒，离别时抱住显影装置不愿放手。三晶星人远也爱她，她却没有把对方的善意变成感情承诺。到了《飞焰》，自己的重生期限迫近，她借远的设备前往八角星，必须及时得到处理才能继续生存；偏偏爱人的灵魂又回到地球，两个方向错开，援救仍在进行。综合终局的曲如眉有长期等待积累的坚韧，也会为了最私人的目标误导旁人。她可以冷静练武、筹划、感谢帮助，却不能因被称为火凤便获得火焰支配或把一次秘密行动当成无所不能。',appearance='有古典侠女气质的美丽女性，神态沉静而幽秘；谈及爱人时情绪明显动摇。',endpoint='前往八角星接受五百年一次的重生程序，是否完成未在末篇确认；没有与回到地球的恋人团聚。',ability=[A('武术与长期生活经验','长期修习中国武术，能理解训练差距并筹划隐秘行动。',['近身自保','判断对手技巧','等待和安排救援'],'不具独立星际运输能力；火箭失窃牵涉外援的说法仅罗开推测。'),A('改造寿命','八角星恋人改变细胞基因，延长生命并要求周期性重生。',['长期保留记忆','跨世代生活'],'五百年须再生处理，错过会死亡；不等于战中即时复活。',kind='生物改造')],evidence=[E(R+'08火凤.txt',528,541,'武术理解'),E(R+'08火凤.txt',1222,1239,'帮助灵魂回乡与离别'),E(R+'15飞焰.txt',1045,1045,'重生期限与航程'),E(R+'15飞焰.txt',1131,1159,'基因来源及火箭事件不确定性')],motivation='与爱人延续真实关系，在长久生存中守住自己的选择。',triggers=[T('援助者期待感情回报','善意变成隐形交换','感谢具体帮助但不许诺自己没有的爱情。'),T('身体周期将到','常规等待无法解决','主动寻求可靠设施并说明时间压力。'),T('秘密关系遭窥探','与公共安全无关','划清边界，必要时只透露合作所需部分。')],scores=(3,1,1,4,1,4),limits=(2,3,1),reasoning='长生并未消除失去的风险，爱情也不能使他人成为应当牺牲的资源。',stamina='寿命很长不等于运动不疲劳；周期性重生是生存刚需。',theoretical='强',uncertainties=['末篇未明确完成再生，部署采用最后已证实可行动的人类形态。'])

rc('bajiaoxing_yingzi','八角星恋人',aliases=['影子','八角星人的灵魂'],roles=['主角','重要配角'],bio='这个没有公布个人姓名的八角星人与曲如眉相爱，地球人主要见到的是显现在平面上的影子。高等生命形式使他能够离开肉体、借装置跨星传送，也曾以基因改变帮助曲如眉延长生命；这些本领却没有使他们免于分别。他回到八角星获得身体后，因为不能立刻重返地球，又以灵魂方式出发，恰与前来重生的曲如眉错过。回到地球的他能记住所接触者的脑活动频率，向旧识发信号，不必先知道对方住址；但每次联系都会消耗能量，显影越来越淡。他误以为远拒绝帮助，听到远已因救曲如眉受到惩罚，才面对另一重无能为力。为了求生，他想到揭穿哈德的机械人身份，迫使对方回应，罗开和高达反对牺牲卡娅的关系，他接受继续等待的办法。综合终局保持的是仍可交流、逐渐衰弱的灵魂，未确认救回。他的高级知识与脆弱处境必须同时出现，不能从“灵魂”二字推出无限能量、任意附体或全知。',appearance='以可明暗变化的影子附显在平面，消耗能量时变淡；没有固定人类肉身。',endpoint='《飞焰》末仍等待哈德等援助，自述能量仅能再支持数日，救援结果未记。',deploy='保持最后可交流灵魂形态与其有限能量；跨世界开场可处于尚未耗尽的同一形态，不宣称原作得救。',ability=[A('旧识脑波通信','保存接触过的脑活动频率，通过神经刺激传递声讯，可在地球寻找相应频率。',['联系旧识求援','共享观察','用显影表达位置'],'须有已接触频率并耗能；不是阅读所有陌生人思想，星际往返须设备。',kind='精神通信'),A('生命改造知识','曾改变曲如眉细胞基因，使其寿命延长。',['在具备条件时分析生命形式'],'衰弱灵魂没有显示能现场任意改造他人；既有长期结果不作即时治疗技能。',kind='知识')],evidence=[E(R+'08火凤.txt',1233,1239,'离去依赖装置'),E(R+'15飞焰.txt',1081,1101,'联系消耗与终局衰弱'),E(R+'15飞焰.txt',1131,1133,'改变寿命的来源'),E(R+'15飞焰.txt',1152,1205,'脑波联系与不许胁迫卡娅')],motivation='维持存在并与曲如眉团聚，必要时接受别人对救援方式的道德边界。',triggers=[T('求援未获回应','不知道对方是否有能力','询问客观障碍，避免把沉默立即当作恶意。'),T('能量持续减少','发送会加速衰弱','筛选最有可能回应的旧识，减少无效呼叫。'),T('别人的秘密能换援助','公开会伤害无关者','先提出请求并接受替代方案，不坚持勒索。')],scores=(0,3,3,1,5,2),limits=(2,4,3),reasoning='生命形式较高仍需要他人帮助，自己的生存也不能抹去别人的感情。',durability='没有常规肉身，普通穿刺目标不适用；能量会消散，未证实免疫各种精神、能量攻击。',energy='有限灵魂能量用于显影与通信，无法无限输出。',mind='能主动刺激已知对象听觉等神经交流；没有全知、全控或精神免疫。',stamina='自述终局仅剩约五六天支持，频繁联系加速衰竭；这是当时状态而非所有场景固定倒计时。',theoretical='强')

rc('yuan','远',roles=['重要配角'],bio='远是罗开接触到的三晶星人，拥有远超地球的科学知识与设施渠道，能够让地球人到观察地带，又将他们送回熟悉的住所。这样的差距很容易使别人把他看成随时解决困难的答案，但他同样有职责、权限和私人感情。他爱曲如眉，知道她爱的是八角星人，却没有因此把帮助变为强迫她改变感情的条件。面对能抑制三晶机械的禇上民，他最先要求罗开解释，对潜在威胁的恐惧真实存在；听到和平共处与不伤害承诺后，他仍接受协助。后来曲如眉必须赶赴八角星重生，远动用了不被许可的设备，因此受到能力大幅削弱的惩罚。影子急切向他发讯息而没有得到救援，罗开提醒众人，他可能已经没有能力出手，甚至自己也困在观察地带。综合终局必须把这个代价留下：他有知识与善意，却不能照搬早先完整权限，更不能让任何朋友通过呼叫他自动获得三晶星全部科技。',appearance='在地球人面前可作可交流的类人形象；原文重点在言谈与技术身份，具体本体结构不详。',endpoint='因私用设备送曲如眉去八角星而受惩罚、能力大幅削弱；未确认恢复。',ability=[A('三晶科技知识与条件性运输','以本族装置和权限实现观测、跨空间或跨星交通。',['解释异常科技','有授权时安排运输','协调机械人协助'],'终局权限及能力已被削弱，不能默认再次进行先前运输；设备不属于所有队友。',kind='外星科技')],evidence=[E(R+'10异人.txt',1385,1394,'警惕天敌后同意合作'),E(R+'15飞焰.txt',1079,1096,'既往运输与受罚削弱')],motivation='在职责与私人情感之间选择具体的帮助，并承担越权的后果。',triggers=[T('天敌提出合作','对方愿明确不侵害','要求解释和约束，再提供自身确能兑现的帮助。'),T('恋人的愿望与自己爱情相悖','援助能保全她的选择','不以爱为条件交换，坦承可用权限。'),T('朋友仍期待万能救援','能力已经受限','说明目前能做的部分，转而共享知识和渠道。')],scores=(1,2,2,2,3,3),limits=(1,4,1),reasoning='强大科技并未消除制度约束，善意要承担实际代价。',energy='历史上借设备完成远距运输；终局剩余独立输出未知，评分从保守可用信息能力。',theoretical='并',uncertainties=['惩罚后具体剩余能力未量化；不能把罗开关于困居的推测写为证实。'])

rc('hade','哈德',roles=['重要配角'],bio='哈德是三晶星制造的机械人，外形与活人相似，体内复杂结构却能让他承担地球人无法完成的航行任务。罗开在《异人》中得知他与卡娅的关系，既惊讶于机械生命能够恋爱，也担心真相被突然揭开。卡娅认为他是理想爱人，却不知道他是机械人；哈德渴望重聚，在谈到她时显出强烈思念，而不只是执行一个模仿感情的指令。他知道禇上民具有削弱三晶机械的能力，对罗开把这个天敌带来极为紧张，但在保证互不伤害后愿意协助。此后他与卡娅离开观察地带，隐居地球，连原机构也未能找到她。到《飞焰》里，垂危的八角星灵魂需要他的运输能力，朋友们仍必须寻找和请求，不能把他当随叫随到的船。综合终局保留的是选择亲密生活的独立机械人格，以及身份隐瞒带来的关系张力；他的身体是高度先进设备，不代表他拥有无限武器或可以代表全部三晶星人作决定。',appearance='与人类无明显差异的男性外观，内部为三晶科技机械结构。',endpoint='与卡娅在地球隐居，身份仍未向她公开；朋友正寻找他援助影子。',ability=[A('三晶机械身体与航行','身体能承担超出地球技术的交通与运载功能，在必要接口条件下前往观察地带。',['跨环境运输','保护同行者','技术信息交流'],'受到禇上民同类能力克制；航行须本人愿意并具备路线条件，不默认星球级攻击。',kind='机械科技')],evidence=[E(R+'10异人.txt',1275,1314,'关系、机械身体与运输'),E(R+'10异人.txt',1349,1394,'天敌、承诺和思念'),E(R+'15飞焰.txt',1137,1205,'隐居、身份与寻找')],motivation='与卡娅维持自己选择的生活，并在互不侵害的条件下帮助旧友。',triggers=[T('有人把机械身体视为工具','忽视他的意愿和关系','先提出个人条件，拒绝不经询问的调用。'),T('克制者请求靠近','有明确不伤害承诺','保持可撤离距离后尝试合作。'),T('旧友处于真实危机','联系渠道可靠','评估运输和伴侣安全，再决定援助。')],scores=(5,4,3,5,4,4),limits=(2,3,1),reasoning='制造来源不能取消人格；保密能保护关系，也可能推迟必须面对的沟通。',durability='高度先进机械躯体，不按普通人血肉处理；具体极温、腐蚀等耐受上限未示，天敌可削弱系统。',speed='有超出地球交通的航行能力，不能据此假定近身反应达到光速。',energy='机体能源与运输科技，具体容量未知；不推为核基地毁灭以外的爆星火力。',theoretical='狂')

rc('shui_hong','水荭',aliases=['水红','鹰的小妹妹'],roles=['重要配角','主角'],bio='水荭是年轻而机敏的情报人员，娇小外形容易使人低估她的行动力。她能调动组织的调查和航空资源，也会把任务带到罗开最不愿被打扰的地方；在《异人》中，她通过卫星照片定位，再乘直升机找来，讲述一个会使固体穿越固体的青年。她愿意先收集录音、影像和证词，而不是仅用权威要求罗开相信。与禇上民相爱后，她不再只是组织观察异常对象的眼睛，而愿意与他共同离开，并接受危险的异星生活。这个转变没有抹去她的诙谐：她会开罗开的玩笑，也会认真保护所爱的人的秘密。后来《飞焰》仍把她写成在职特工，与原体高达有感情牵连，并正受组织疑难任务困扰；两段关系与离开计划的时序没有得到完整说明，不能替原著补出婚姻和归宿。综合终局采用末篇仍可行动的特工形态，保留她选择爱情与追问异常的经历。她是可靠的联络者，也需要被保护和理解，不能因为叫小妹妹就被剥去专业判断。',appearance='娇小年轻的成年女性，常穿红色，神态俏皮，外观近似大学低年级学生。',endpoint='《飞焰》末仍在组织任职，表示以后或离开；《异人》与禇上民赴观察地带的安排未说明后续，保留时序疑点。',ability=[A('情报调查与联络','整理证词影像、请求卫星侦察和航空资源，协调人员。',['定位目标','秘密会面','辨别异常证据'],'资源属于机构须权限，卫星不是个人全知；离开组织会失去部分渠道。')],evidence=[E(R+'07蜂后.txt',1160,1165,'与高达及罗开关系'),E(R+'09夜光.txt',669,687,'水红写法及形象'),E(R+'10异人.txt',1,75,'定位、组织与录音调查'),E(R+'10异人.txt',1332,1395,'爱情、承诺与离开计划'),E(R+'15飞焰.txt',1212,1227,'在职终局与未来意愿')],motivation='把任务做清楚，也要有权选择自己爱的人和生活。',triggers=[T('异常对象被视为威胁','只有能力特殊而无伤害证据','补充实际观察，主张沟通而非直接消灭。'),T('私人关系妨碍任务','组织要求无条件服从','说明可执行范围，寻找退出或交接办法。'),T('有人因外貌轻视她','忽略已带来的资料','用可核实结果回应，仍能以玩笑化解紧张。')],scores=(2,0,1,3,2,4),limits=(2,2,1),reasoning='机构身份提供工具，不应取代本人对善恶与亲密关系的判断。',uncertainties=['系列内感情与是否离开机构存在未交代的连续性，卡片不强行合并为已婚终局。'],theoretical='并')

rc('chushangmin','禇上民',aliases=['褚上民'],roles=['主角'],bio='禇上民由地球女性阿清孕育，在地球成长和受教育，却是失事异星来客留下的胚胎。他与人类外形相同，能使固体穿越固体，这一能力令情报机构把他当成需要秘密研究乃至消灭的异常。罗开最初也以为封闭瓶里的展示是魔术，调查后才不得不承认既有知识不足。禇上民本人不像掌握力量的征服者，他对外界谨慎，出远门时会像初进大城的青年一样紧拉水荭衣袖；他需要家乡的消息，也在意自己真实的身体和地球养成的感情。面对三晶机械，他会本能地感觉那是一种过强的奇怪东西，产生让其力量减弱的念头，这使双方互为天敌，但他明确说想法不等于必须去做。罗开提出不伤害机械人、不得向卡娅揭穿哈德身份，他与水荭都答应，并通过互信争取前往观察地带的机会。综合终局保留这种强能力与不成熟社会经验并存的状态；他并不知道自己的星球在哪里，也不能因穿透固体就被赋予任意空间、时间或概念控制。',appearance='年轻男性，人类外形，有血有肉；紧张时会显得拘谨而依赖熟悉的人。',endpoint='与水荭获准前往观察地带寻找故乡，是否回到本星未确认。',ability=[A('固体穿越','异星生物能力使固体通过另一固体，封闭容器实验可观察。',['越过实体阻隔','取放受封物件','辅助撤离'],'未示无限规模或对任何能量屏障适用；本人仍珍惜血肉身体。',kind='异星能力'),A('三晶机械克制','能感知三晶机械的异常力量，并有削弱或消除它的能力倾向。',['察觉特定机械','必要时阻止机械威胁'],'仅有针对性生物相克依据，不泛化为抹除全部机器或力量；主动承诺不攻击。',kind='特异克制')],evidence=[E(R+'10异人.txt',169,177,'封闭瓶展示'),E(R+'10异人.txt',1332,1366,'身体认知与天敌克制'),E(R+'10异人.txt',1376,1395,'穿越、和平承诺与终局')],motivation='与水荭平安生活、寻找故乡，并证明能力差异不必导致互相消灭。',triggers=[T('被要求展示异能','对方愿尊重其身体与退出权','选择小规模可观察方式证明，不接受无限实验。'),T('感到三晶机械逼近','本能想压低对方力量','先说明感受并拉开距离，除非确有侵害不攻击。'),T('陌生环境需要决定','没有足够社会经验','向信任的人求助，同时说清自己的意愿。')],scores=(2,4,2,3,2,3),limits=(3,2,1),reasoning='能够伤害不等于必须伤害；保住关系比证明力量更重要。',energy='固体穿越和特定机械削弱；机制未完全解释，不能升级为规则级改写。',mind='有特殊感知与控制能力，未证实读取普通人思想或抵御一切精神攻击。',theoretical='强')

rc('meigui','玫瑰',roles=['主角'],bio='玫瑰在调查海上夜光事件时与罗开相识，自称本来该叫黄玫瑰，却要求只用玫瑰这个名字。她美丽、机敏，颊上的小蓝痣给人鲜明印象，也熟悉一些远超普通旅人的消息。罗开想知道她的来历，她请求不要追问，还暗示世上不只有一个自己。后来高达说香港有一个同名同貌的女子，这个线索没有在原文中被证实为同一身份或复制事实。面对掌握广泛资料的三晶机械，她在掌心写下秘密信息，希望查清某个身份，又在结果前表现出明显紧张，迅速擦掉字迹。罗开选择尊重她未公开的部分，她才进一步说明另有一股非地球力量也在查康维十七世。故事结束时，康维与玫瑰一样仿佛在记录中不存在，而她仍是能交谈、行动和选择隐瞒的真实人物。综合终局让她保持这种调查者与被调查者重叠的位置；身份谜团是行为动机的边界，不是可以任意填入分身、神力或幕后全知的空白授权。',appearance='美丽的成年女子，脸颊有一颗小蓝痣；神情可以亲切，也会突然变得戒备。',endpoint='《夜光》身份未解，未被确认与香港同名女子为同人，也未证明为外星人。',ability=[A('敏锐交涉与信息保密','观察事件与人物，利用已知渠道询问资料，并控制自身身份暴露。',['秘密调查','以少量信息换帮助','拒绝无关窥私'],'未知身世不作超能力依据；机械人的数据库不是她的个人能力。')],evidence=[E(R+'09夜光.txt',591,601,'名字、外貌和苦衷'),E(R+'09夜光.txt',1250,1282,'同名线索、保密与外部调查')],motivation='寻找与自身处境有关的答案，同时保留不被外界强行定义的空间。',triggers=[T('合作者追问身世','问题与当前行动无关','明确请求停止，提供合作所需的有限资料。'),T('数据库给出不存在','自身经历并未因此消失','追问数据范围和检索条件，不立即否定自己。'),T('出现同名同貌者','没有独立核验','保持多种解释，寻找能区分身份的事实。')],scores=(1,0,1,1,1,2),limits=(2,2,1),reasoning='秘密可以有真实苦衷；尊重边界才能换取进一步合作。',uncertainties=['她的真实姓名、非地球力量关系及同名者身份没有解答。'],theoretical='纸')

rc('night_robot','夜光事件的三晶星机械人',roles=['阶段性对立者'],bio='罗开在夜光事件中追查到的三晶星机械人不是一件单纯被遗弃的工具。它掌握大量电脑资料，能够按程序检索人物，却对来历与反叛经历保持沉默。玫瑰希望藉它查身份，罗开则要弄清康维十七世，它给出的结果反而令两个看似真实存在的人变得更难解释。罗开意识到自己无法用耐心压过机器：同样的话，它可以重复极久。于是他改口提出找三晶星人远来见它，又点破它曾背叛制造者。这个提议让所有闪亮点停止，机械人此后不再回答。这里的对立不是已证实的毁灭地球计划，而是一个有自身立场的机器拒绝被调查者支配。综合终局保留资料处理与自主拒绝的两面，不把它与哈德或康维合并，也不从同族型号推定相同火力。它适合推动信息交换、身份核验和制造者责任的冲突；当问题触及自己的处境时，沉默本身就是行动，而不是角色失去叙事作用。',appearance='以带有许多闪亮点的机械形态被观察，停止响应时光点静止熄暗。',endpoint='《夜光》听见找远来后沉默；罗开未能找到远，身世与反叛理由未解。',ability=[A('广泛电脑资料检索','以自身资料或连接按特定程序查询身份记录。',['检索线索','比较人物资料','拒绝或中断输出'],'声称资料全面不等于世界全知；查无记录不能否定实体存在，攻击能力无明确展示。',kind='信息技术')],evidence=[E(R+'09夜光.txt',1237,1262,'资料程序与查验'),E(R+'09夜光.txt',1283,1292,'反叛、沉默和未解终局')],motivation='保持自身处境与信息边界，不因制造来源被强迫回答一切。',triggers=[T('请求符合检索条件','不触及自身禁区','依实际数据给出结果，标明未找到。'),T('制造者被用来施压','询问者没有授权解释','停止信息输出，等待可接受的交涉方式。'),T('人类把查无记录当不存在','结论超出资料','以检索范围纠正，避免变成全知裁判。')],scores=(1,1,2,4,2,1),limits=(2,3,1),reasoning='资料控制也是自主行动；同族不是同一个人格。',durability='机械形态，不假定与人类同样损伤；原文没有足够抗打击数据。',theoretical='并',uncertainties=['反叛原因、资料实际覆盖和武装配置均未知。'])

rc('leixue','雷雪',roles=['主角','重要配角'],bio='雷雪拥有许多人想要而她自己痛苦的能力：她能知道别人的思想。旁人看到的是美貌和与高达的关系，她却拒绝被一句“高达的女人”概括，也无法靠漂亮外表隔绝不断进入意识的内容。天神之盒引起她强烈的死亡感受，她并不立刻理解全部讯息，必须把杂乱刺激逐步整理。许多盒子突然滚动时，她会尖叫、颤抖，后来推断整齐排列能使讯息有序，这才让调查获得进展。她通过握手使安歌人、温宝裕和罗开短暂感到相同的恐惧；机械人康维和异星扁平人却毫无反应，说明这不是通吃所有生命的死亡权能。她最终读出所谓解结必须放弃肉体生命，自己也没有选择那条路，只能继续面对感知思想带来的痛苦。综合终局不把她写成随时准确念出所有秘密的解说器：她需要环境、整理和情绪承受力，会希望得到真正的安静与被当作一个人对待。',appearance='美丽年轻的成年女性，声音悦耳；过强讯息会使她面色紧张、颤抖和出汗。',endpoint='拒绝以死亡换天神许诺，仍保有读心能力及相伴痛苦。',ability=[A('思想与特定讯息感知','能接收他人思想以及盒子对人脑的讯息，通过接触暂时转递。',['识别意图','解读异常讯息','让他人验证同一感受'],'讯息可能杂乱、移动会干扰并致痛；盒子死亡感受只对适配人脑有效，不是她任意发布的死亡命令。',kind='精神感知')],evidence=[E(R+'12解开死结.txt',912,919,'独立人格及能力'),E(R+'12解开死结.txt',1218,1255,'干扰、接触转递和适配边界'),E(R+'12解开死结.txt',1256,1278,'整理、解释与终局')],motivation='理解自己的能力并减少痛苦，不以失去生命和人格求解脱。',triggers=[T('讯息过多','身体开始颤抖或难分来源','暂停接触、整理物件和空间，请求别人安静协助。'),T('他人把她当情人的附属','忽视她正在作的判断','直接纠正称呼，继续说明自己的结论。'),T('需要别人相信不可见感受','对方愿意且适配','先解释风险再短暂接触，异常立即停止。')],scores=(1,3,2,1,2,2),limits=(2,3,3),reasoning='知道别人的想法不等于愿意承受所有想法，也不等于知道一切答案。',mind='明确有读心及讯息接收，过载会痛苦；未示精神免疫或无限控制。',energy='精神信息作用，盒子讯息来源外在；不计作物理杀伤能量。',theoretical='并')

rc('jinaihua','金艾花',roles=['阶段性对立者'],bio='金艾花是金取派第三十七代传人，也以帮主身份主持行动。这个流派的名字和偷取传统给她鲜明来历，她却没有把身份做成庄严不可接近的面具：面对罗开，她会调笑、主动证明自己的训练，并以高度柔韧的身体控制显示多年练习。罗开难以理解，一副棋子为何值得这样的人亲自出手，她的委托与师弟的事才逐渐露出关联。棋子盗取、冒似人物与勒索录像交错，使她一度像整场国际威胁的中心；后续揭示真正的音波破坏和筹款指令来自天上基地，她的本领不能解释那些规模。综合终局保留她作为具体窃盗者、门派传人和有私人义务的行动者，而不把所有外星阴谋归给她。她会借别人的注意力空隙取物，也会高估魅力能掩盖多少问题；遭遇远高于自己层次的科技时，专业自信应转成谨慎调查。角色的鲜活处在于她能谈条件、维护门派和承认信息不足，不是每个场景都重复一种诱惑姿势。',appearance='韩国女性，身体柔韧，能细致控制肌肉与动作；仪态轻巧而自信。',endpoint='《困兽》的取棋与调查牵连人物；不能证明她拥有后段外星基地破坏能力。',ability=[A('金取派窃盗与身体控制','门派训练用于接近、偷取和柔韧动作。',['隐蔽取物','从拘束姿势脱出','观察对手注意力'],'依赖接近和现场条件；没有复制自己或发射破坏音波的个人能力。')],evidence=[E(R+'13困兽.txt',170,193,'身份与身体训练'),E(R+'13困兽.txt',244,262,'棋子目标与私人关联'),E(R+'13困兽.txt',484,488,'影像造成的疑问'),E(R+'13困兽.txt',939,948,'真正勒索执行来源')],motivation='维护门派专业和私人承诺，在不透明委托中保留退路。',triggers=[T('小目标牵涉巨大报酬','任务规模与理由不相称','先追问真正受益者，不只展示盗术。'),T('影像把罪行扣给她','事实与自己行动冲突','核对时间、来源和仿冒可能。'),T('有人低估训练','仍可用无害动作证明','展示有限技巧后转谈条件，避免为自尊冒险。')],scores=(3,0,0,2,1,4),limits=(1,2,1),reasoning='技巧可以取得物件，却不能替代对委托后果的判断。',theoretical='并')

rc('yunxian','云仙',aliases=['天上人间首领'],roles=['反派','主角'],bio='云仙是被宇宙航行者从地球带走的女孩，在天上基地长大，成年后掌握二十名任务执行者的指挥权。她知道自己是地球人，却不了解地球上的钱、语言和社会关系，日常判断来自资料库。航行者教她，当大量人脑活动共同表示身处困境，地球图上会出现红色，需要查资料并派人援助；她照着指示，希望让困兽般的人重获自由。问题出在她选择最快筹款方案：以音波破坏展示力量，再向目标勒索。她不是不知道自己作了决定，而是不理解这些程序落到人群中意味着什么，反以资料库不会错为理由放心。罗开到来后，她学会面对一个不能被数据流程替代的具体他人，并开始补课。六个月后她能说多种语言，为自己取名云仙，又把两人的亲密理解成婚姻，留下新的误解。综合终局她仍握有危险的机构资源，但已经开始学习社会；不能把天真当免罪，也不能把二十名执行者的设备变成她的身体天赋。',appearance='美丽年轻的成年地球女性，初期戴翻译头罩，动作好奇直接；后期会地球语言。',endpoint='六个月学习后回地球与罗开相见，自取名云仙并认定夫妻关系，双方未就此达成明确共识。',ability=[A('基地决策与学习','依据外星资料库、监测仪和执行者完成决策；自身学习语言迅速。',['解析援助请求','指派有限任务','学习新的社会规则'],'本体是人类；装备和二十执行者为有条件资源，资料库输出不能保证道德正确。',kind='机构指挥')],evidence=[E(R+'13困兽.txt',895,925,'地球身份、二十执行者与监测'),E(R+'13困兽.txt',931,950,'自行选择勒索和音波破坏'),E(R+'13困兽.txt',1005,1028,'学习与名字、关系认知')],motivation='帮助被困的人并建立自己的生活，同时学习为自己作出的决定负责。',triggers=[T('系统给出最快方案','实际会伤害未参与者','要求解释受害者与替代办法，不仅看效率。'),T('复杂关系无法归类','书本答案与当事人意见冲突','直接询问对方意愿，允许修正结论。'),T('群体急需援助','监测与现场消息一致','先确认具体需要，再限制执行者的任务范围。')],scores=(1,0,1,2,1,2),limits=(3,3,2),reasoning='资料库可以提供方法，不能替人承担选择造成的后果。',theoretical='并',uncertainties=['执行者是否机械生命没有足够明确文本，按独立设备操作者处理。'])

rc('executors','天上人间任务执行者',roles=['反派','阶段性对立者'],bio='任务执行者是宇宙航行者留给地球女孩的二十名助手，穿戴、身高和声音相同，罗开不能区分个体，原文也未给他们个人姓名。他们依据首领的决策和资料库完成行动，能驾驶往返地球的设备、解释监测资料，并以精神影响推动本来已有反抗意愿的人。四名执行者被派去筹款后，选目标、写恐吓信、展示音波破坏和处理银行手续，形成看似由阴谋集团主持的勒索。其目的被解释为帮助身处压迫中的人，手段却确实造成恐慌与损失。面对罗开的追问，他们愿意说明能力边界：只能推波助澜，不能让根本不愿改变的施害者突然悔悟；地球图没有出现共同求助信号，也不会主动介入。综合终局不能把这种自我说明变成绝对善良保证，但能作为协商入口。他们适合被迫面对程序与后果之间的裂缝，逐步把“完成任务”细化为当事人可接受的援助，而不是一群无限召唤、绝对服从且无成本的外星兵器。',appearance='一组矮身、同样装饰和头罩的执行者，眼部有光，个体无法从正文稳定区分。',endpoint='继续由云仙管理的有限二十成员群体；筹款破坏来源得到揭示。',ability=[A('设备执行与有限脑活动影响','利用基地科技往返、音波震毁及加强既有意愿的精神干预。',['破坏被选目标','运输和调查','催发本已存在的行动意愿'],'只有二十成员，强破坏依赖设备；不能违背一切思想任意控心，不会自动继承全部航行者科技。',kind='外星技术与精神影响')],evidence=[E(R+'13困兽.txt',846,909,'来源、形态与二十成员'),E(R+'13困兽.txt',939,948,'四名执行者的勒索破坏'),E(R+'13困兽.txt',991,1002,'精神影响边界')],motivation='执行真实求助区域的援助任务，但须面对方法本身可能伤害他人。',triggers=[T('收到首领指令','资料与指令冲突','提出可执行边界，说明方案需要的设备和代价。'),T('目标意愿不相容','影响只能顺势','停止把催发当改心，改用交涉。'),T('任务造成无关损失','当事人提出具体证据','重新核对援助目标与程序，接受调整方案。')],scores=(3,5,3,4,4,4),limits=(3,3,1),reasoning='任务目标不能自动证明执行程序正确；能力边界会使简单命令失效。',energy='设备可用音波毁坏目标；未量化城市覆盖，不升级为行星火力。',mind='能增强已有思想和传达指令，明确不能令相反意愿者任意悔悟。',theoretical='狂')

rc('buji','布姬',roles=['主角','阶段性对立者'],bio='布姬是没落王朝的公主，身负族人重建昔日权势的希望。她提出看似难以理解的要求：在限定时间内取得荷兰制造的核潜艇，不愿随便换成其他工具。罗开起初面对的是一项任务，随后才知道潜艇用于深海探测，目标是被狮神保存的祖先游魂与开国智慧。她能操作复杂设备，耐心守着荧光屏，连休息也担心错失异常；但没有人知道魂魄究竟会以什么方式出现，技术熟练并不能填补这个认识空洞。随着长久海下相处，她和罗开讨论古代经验是否还能用于现代，也承认复国会带来战争和死伤。她答应即使真的找到智慧，也不参与重建王国，最后仍驾驶潜艇回到族人身边，让他们继续寻找。综合终局的布姬不是已经获得祖先权能的女王，而是在家族期望与个人生活之间作出有限退出的人。她可以尽责完成交接，也可以拒绝把自己的未来全部献给一桩没有验证的宏愿。',appearance='年轻美丽的成年女性，神情聪慧；操作仪器时专注，对族中禁忌会显得谨慎。',endpoint='海下搜索没有发现，独自驾艇回族人身边，承诺不参加复国行动。',ability=[A('潜艇操作与专注搜寻','学习并操作先进潜艇探测、监视和航行系统。',['深海探索','避开陆地追踪','分析仪器异常'],'须实际拥有可用潜艇及补给；没有召唤、附体或祖先智慧已经接收的证据。')],evidence=[E(R+'14游魂.txt',1205,1234,'仪器与目标认知不足'),E(R+'14游魂.txt',1258,1283,'复国设想与承诺'),E(R+'14游魂.txt',1297,1304,'无果搜索与独自离开')],motivation='保留家族身份与责任，却不让复国愿景吞掉自己的生活。',triggers=[T('家族要求承担历史使命','将造成新的战争伤亡','重申个人承诺，提供非战争的替代帮助。'),T('技术没有预设目标特征','搜寻对象尚未验证','先建立可观察判据，不把所有异常当神迹。'),T('交接与私人愿望冲突','任务必须有人完成','完成有限交接后争取自己的时间。')],scores=(1,0,1,2,1,2),limits=(2,3,1),reasoning='旧王朝的智慧并未被找到，身份也不构成参与战争的义务。',theoretical='并')

rc('gaoda_copy','高达复制体',aliases=['与蜂后隐居的高达'],roles=['主角','阶段性对立者'],bio='这个高达由勒曼医院制造，身体来自原体细胞，脑内则被植入原体对蜂后的爱情记忆，以及制造者希望他执行的意念。他因此在外表、遗传与部分经历上都像浪子高达，却不能简单视为原体某次换了性格。原高达长期浪子生活压抑了表白，他却毫无顾忌地爱蜂后，使她认定眼前的真诚不是伪装。制造者原想藉复制人对付蜂后王国，并让他向罗开下手；他确实一度使罗开昏迷，随后却凭自己的意念立即救醒对方。这个矛盾让罗开抓住关键：复制出来的仍然是人，会发展自己的思想，不能被注入命令永远定义。组织最后停止干预，他与蜂后离开，从哥本哈根转往马达加斯加后摆脱跟踪。综合终局采用这个愿意选择专一生活的独立个体，不与继续当浪子的原体合并，也不自动复制原体后来所有冒险、技能和人脉；他有爱情起源被安排的困惑，但已经以抗命证明接下来的决定属于自己。',appearance='与原体高达相同的男性外貌和遗传身体，谈及蜂后的感情更直接。',endpoint='与蜂后共同隐居，下落不明；原体高达另在继续冒险。',ability=[A('复制身体与自主抵抗','具备高达复制身体及已植入记忆，能够反抗外加意念并作救人选择。',['有限近身行动','抵抗制造者意念','借原体外貌应对身份盘查'],'完整技能和后来记忆未确认；抵抗一次不等于精神免疫，不能与原体远程同步。')],evidence=[E(R+'07蜂后.txt',1122,1155,'爱情来源、复制与抗命救人'),E(R+'07蜂后.txt',1157,1162,'原体与复制体分离终局')],motivation='与蜂后过自己选择的生活，拒绝再被当作可牺牲的器官和命令载体。',triggers=[T('有人称他是替用品','否定其正在作出的选择','以具体意愿和行为回应，拒绝接受处置权。'),T('外加冲动与保护他人冲突','能察觉行动后果','中止伤害，寻找解除控制的协助。'),T('原体出现','外人要求两人合并身份','承认共同起源，明确各自关系与经历。')],scores=(3,0,1,3,1,4),limits=(2,1,2),reasoning='来源被安排不等于未来必须被安排；独立选择比证明自己更像原体重要。',mind='有抵抗注入意念的明确实例，但也先受控伤人；非全面精神免疫。',theoretical='并')

rc('shuiyin','水银将军',roles=['重要配角'],bio='水银将军是黛娜的上司，习惯以文件、报告和任务构成对世界的认识。他并不是只相信机构级别的人：听到海底洞穴的异象时，他特别重视一位二战期间结识的奇人都加连农，知道常规报告无法穷尽真实情况。他把黛娜派去调查，也会利用她与罗开的私人关系接洽重要事务，让不喜欢组织束缚的罗开产生反感。这种工作方式体现情报首脑的效率，也暴露了把私人关系当渠道的倾向。复制玩偶送回办公室时，他起初把突然缩小的叙述视为怪谈，却不得不面对已存在的实物；后来以高额报酬寻求罗开协助，又牵涉不同国家同时关注的怪头疑案。综合终局，他仍是有权调度但受机构目标限制的指挥者，不因职衔就拥有部属全部本领或外星装置。他可以提供调查条件、鉴别报告来源、安排任务，也必须承受独立冒险者的拒绝。新场景应把他写成会算资源和责任的人，既非天生邪恶上司，也非无限兑现支援的万能联系人。',appearance='成年男性军官，目光深邃，办公与交谈时常先审阅文件再提问题。',endpoint='在《妖偶》《怪头》中持续担任情报上司，后续个人去向没有进一步说明。',ability=[A('情报判断与机构调度','依据可靠线人、报告和权限安排调查、资金与人员。',['提供调查入口','核验来源可信度','协调机密行动'],'需组织权限和真实资源；私人关系只能请求，不能强令罗开。')],evidence=[E(R+'02妖偶.txt',1020,1037,'旧识与报告判断'),E(R+'02妖偶.txt',1317,1319,'玩偶与认知限制'),E(R+'04怪头.txt',516,532,'任务和报酬')],motivation='把异常纳入可调查、可管理的范围，维持机构行动效率。',triggers=[T('普通报告与可信旧识冲突','旧识有已验证专长','提高调查优先级而不先下结论。'),T('独立专家拒绝任务','对方不承认机构指挥权','改谈条件和必要性，接受有限合作。'),T('物证突破既有常识','继续否认会阻碍判断','安排验证和隔离，修正最初推测。')],scores=(1,0,1,2,1,2),limits=(2,3,1),reasoning='职权能组织调查，不能代替事实或买到任何人的服从。',theoretical='并')

rc('spoda','斯波达星追捕者',roles=['阶段性对立者'],bio='这两名斯波达星人以追捕时间大神为任务，与罗开并非从一开始就互为敌人。他们说明来历，认可罗开曾经对付共同敌人，掌握能够跨越人类认知的设备和脑能力。任务一旦进入紧迫阶段，他们却选择封闭时间大神逃入的山洞，明知罗开和卡娅也在里面，仍把两个人的生命放在防止宇宙祸患逃脱之后。罗开从盟友变成可被牺牲者，恰好暴露了不同尺度责任之间的冲突。留在洞里的仪器后来成为脱困关键，时间大神反而以残存能力解释怎样借脑活动驱动装置，和两名地球人暂时合作逃出去。综合终局中的斯波达追捕者不能被写成已经完成彻底消灭敌人的正义胜利者，也不能因使命高远自动获得道德豁免。他们的技能依赖具体设备、能量和行动判断；新场景让他们面对同样的取舍时，可以被要求提供撤离方案和风险说明，而不是永远把低技术生命当成无须询问的损耗。',appearance='两名可与地球人交谈的外星人，遗留衣物与仪器；原生形体未充分描写。',endpoint='封闭山洞后离开，时间大神最终仍脱困；追捕后续未交代。',ability=[A('追捕与脑能设备','以外星仪器攻击、封锁和控制通路，装置可由适配脑活动供能。',['压制特定敌人','封锁山洞','仪器侦查和协同'],'攻击未证明能彻底抹灭时间大神；封锁可能伤及同伴，具体设备必须在场。',kind='外星技术')],evidence=[E(R+'04怪头.txt',772,774,'身份与合作'),E(R+'04怪头.txt',1233,1260,'封山与牺牲地球人'),E(R+'04怪头.txt',1281,1345,'遗留设备和敌人脱困')],motivation='阻止时间大神继续危害，同时在被质问时面对任务代价。',triggers=[T('敌人即将逃脱','封锁会困住无关者','先核对撤离机会；若仍封锁，承担并说明代价。'),T('低技术盟友提出异议','其亲历事实与计划冲突','听取现场信息，不以文明等级免除说明。'),T('设备落入敌手','对方能理解接口','调整封锁与追踪，不能假定科技永远不可反用。')],scores=(3,5,3,3,4,5),limits=(2,3,1),reasoning='宏大使命不抹去可见生命，技术优势也不保证无漏洞。',theoretical='狂')

rc('dragon_crew','巨龙机械机组',roles=['阶段性对立者'],bio='巨龙内部的机械机组使四千年前的神话显露出另一层实物结构。罗开和燕艳看见十名暗红色的操作者，最初只有一个在光照后恢复行动，它要求光，说明眼部摄入的能量是维持活动的关键。它袭击罗开，被摔撞在石台后散成零件，余下九个仍缺少动力。控制室录像显示，这套巨龙装置曾发出黄色光束击落飞船，也把一批批女性运走；后者推翻了把她们当食物的传言，却没有使强制运输变成自愿。再后来天空战争与装置失效留下遗迹，具体主人与战略不完全清楚。综合终局不能把历史武器威力等同每个机械人的拳力，也不能把已毁个体自动算回可用数量。这个群体条目只代表剩下可由光源激活的九个操作者及其共同程序，巨龙平台必须另行获得、供能并学会操作。它们的对立性来自攻击和执行运输，而非长得不像人；当原指令失去主人，是否继续服从也可成为明确标注的演绎问题。',appearance='暗红色外表的类人机械结构，损毁后显露可拆散零件；眼部能接收光源。',endpoint='十个中一个被击毁，九个缺能停机留在巨龙内部；平台没有被罗开或燕艳正式掌控。',deploy='以九个存留机体为上限，提供真实光源后可恢复活动；巨龙武器不是默认随身装备。',ability=[A('光能机械操作','以眼部受光恢复活动，执行既有平台操作和近身动作。',['操纵已授权装置','守卫内部区域','处理运输程序'],'须光能；普通机体可被强力摔撞拆毁，失去平台不再有历史光束火力。',kind='机械技术')],evidence=[E(R+'05巨龙.txt',1203,1238,'光源、攻击与机体毁坏'),E(R+'05巨龙.txt',1248,1273,'录像、运输、停机与九个存留'),E(R+'05巨龙.txt',1283,1283,'平台威力仍在但未掌握')],motivation='执行残存任务与维持运作，遇到新指令来源时需核验权限。',triggers=[T('光源恢复','能源达到可活动条件','先检查系统与指令，不凭苏醒就掌握新环境。'),T('陌生者操作平台','授权不明','阻止接近核心，使用有限手段确认意图。'),T('原指令涉及强迫运输','当事人反抗且主人不在','演绎接口：暂停核验目标与权限，而非自动新增善恶判断。')],scores=(3,1,1,2,1,3),limits=(1,4,1),reasoning='历史战场记录不能证明现有九机体能独立重演全部火力。',durability='机体会被强摔散架；没有坦克级装甲证据。',theoretical='并',adapt=[{'change':'在主人缺位时加入指令核验与暂停接口。','reason':'让机械群体可参与互动，而非只有重复攻击。','power_impact':'不增加火力、能源或机体数量。'}])

rc('xia_brothers','夏氏兄弟',roles=['反派'],bio='夏氏兄弟是新兴人口贩卖集团的首脑，利用财富市场对人的需求组织犯罪。他们用一笑一哭两个面具作标记，声称顺从便有欢乐、得罪就要受苦，把威胁包装成一套简单而易识别的秩序。与高达发生冲突后，他们让两名女子携带小盒到他身边，盒子实为会爆炸的装置，执行者的生命显然不在保护范围内。罗开从刺青辨认出集团，询问后发现女子还相信下月赴中东演时装的说法，不知道自己可能被出售。原文没有充分区分两位首脑的姓名、外貌和个人经历，因此本条只记二人共同领导的犯罪身份，不虚构兄弟之间的性格分工。故事中的炸毁与伪装死亡另牵涉高达布局，不能推为集团已经彻底消灭。综合终局让他们作为依赖招募谎言、暴力威慑和代理袭击的地球罪犯活动；他们不是能随意控制人心的组织，也没有比特定爆炸装置更高的个人战力。每次犯罪都需要渠道、人员和掩饰，受害者获知真相会直接破坏其控制。',appearance='二人本人的外貌未详；集团以一笑一哭双面具为识别记号。',endpoint='《妖偶》中人口贩卖与针对高达的爆炸手段被识破，二人最终法律结局未载。',ability=[A('欺骗招募与代理袭击','借虚假演出工作招募女子，用集团标记和恐吓维持服从，派人运送爆炸物。',['隐蔽接近目标','制造袭击','牟取非法收益'],'必须有真实人手、爆炸装置和运输渠道；代理人得知真相可能脱离。')],evidence=[E(R+'02妖偶.txt',302,303,'集团身份与标志'),E(R+'02妖偶.txt',323,330,'爆炸物及被欺骗女子')],motivation='通过剥削和恐惧维持收益，对妨碍生意者报复。',triggers=[T('渠道被熟人识破','受害者将得知真相','优先封堵消息与撤走联络人，暴露其对信息控制的依赖。'),T('目标防备正面袭击','仍可能接受无辜来客','借代理接近而隐藏危险装置。'),T('收益与下属安全冲突','能保全首脑而牺牲代理','倾向牺牲代理，给对手救人和离间的机会。')],scores=(1,0,1,1,2,2),limits=(1,3,1),reasoning='将他人当商品和消耗品，服从来自欺骗与恐惧而非忠诚。',theoretical='并')

